import{_ as e,o as t,c as i,a2 as l}from"./chunks/framework.Cms9CC3y.js";const p=JSON.parse('{"title":"罐容表配置说明","description":"","frontmatter":{"title":"罐容表配置说明","date":"2026-10-14T16:03:19.000Z","lastmod":"2026-11-24T18:42:14.000Z"},"headers":[],"relativePath":"guide/1293.md","filePath":"guide/帮助文档/配置说明/系统配置/储罐配置/罐容表配置说明.md"}'),r={name:"guide/1293.md"};function o(n,a,_,s,d,h){return t(),i("div",null,[...a[0]||(a[0]=[l('<h1 id="罐容表配置说明" tabindex="-1">罐容表配置说明 <a class="header-anchor" href="#罐容表配置说明" aria-label="Permalink to &quot;罐容表配置说明&quot;">​</a></h1><hr><h3 id="_1-功能描述" tabindex="-1">1:功能描述 <a class="header-anchor" href="#_1-功能描述" aria-label="Permalink to &quot;1:功能描述&quot;">​</a></h3><p>管理罐的容积表和静压表</p><h3 id="_2-如何使用" tabindex="-1">2:如何使用 <a class="header-anchor" href="#_2-如何使用" aria-label="Permalink to &quot;2:如何使用&quot;">​</a></h3><p>在储罐配置界面，选中要配置的罐，点击 &quot;罐容表配置&quot; 按钮打开：</p><h3 id="_3-操作说明" tabindex="-1">3:操作说明 <a class="header-anchor" href="#_3-操作说明" aria-label="Permalink to &quot;3:操作说明&quot;">​</a></h3><p>需要清空容积表,重新输入所有数据,请点击此按钮</p><p>需要清空静压表,重新输入所有数据,请点击此按钮</p><p>与老版本EntisC+兼容,可以把罐容表导出为Entis C+能够识别的格式</p><p>与老版本EntisC+兼容,可以导入Entis C+的罐容表格式文件</p><ul><li>此功能要求本机安装有 Excel 2010 或以上版本。</li><li>在导入时，具体设置要参考客户提供的 Excel 文件的格式。请确保导入的数据在 Excel 文件第一个 Sheet（单元表）中，否则无法识别。</li><li>对罐容表的数据条目没有任何限制，每个罐导入 10 万条罐容表也不会有任何性能问题。但在导入过程中，数据越多，导入会越慢，需要耐心等待。</li><li>软件中默认高度单位为毫米，如果客户提供的单位不是毫米，则在单位转化设置中设定。</li><li>软件中默认体积单位为立方，如果客户提供的单位不是立方，则在单位转化设置中设定。</li><li>如果客户的容积表和静压表放置在不同的文件中，则可以分别导入。不导入的部分可以去掉选中状态。</li></ul><p>导入数据后，请切换显示到图表界面，如图：</p><h5 id="" tabindex="-1">--- <a class="header-anchor" href="#" aria-label="Permalink to &quot;---&quot;">​</a></h5><p>使用导入功能，默认都会清除罐容表中原先的数据。在导入 Excel 时，如果选择了保留原有数据则不会清除，只会追加。设置完成后，点击确定之前，请确认已关闭要导入的 Excel 文件。</p>',15)])])}const u=e(r,[["render",o]]);export{p as __pageData,u as default};
